# Synthetic teaching data. Base R only; run from this directory.
set.seed(722)
blue<-'#287f91';orange<-'#bd633e';gray<-'#b8b8b8'
start<-function(id,k){png(sprintf('assets/gallery-%s-%d.png',id,k),1100,800,res=130);par(mar=c(5,5,3,2),las=1,bty='l')}
# Radar profiles, common percentage scale.
r<-rbind(c(80,45,65,30,75),c(55,70,40,65,50));colnames(r)<-c('Enzyme A','Enzyme B','Enzyme C','Enzyme D','Enzyme E');rownames(r)<-c('Strain A','Strain B');write.csv(r,'data/gallery-radar.csv')
radar<-function(which){a<-seq(pi/2,pi/2+2*pi,length.out=6)[1:5];plot(NA,xlim=c(-1.45,1.45),ylim=c(-1.4,1.4),asp=1,axes=FALSE,xlab='',ylab='');for(q in c(.25,.5,.75,1)){polygon(q*cos(a),q*sin(a),border='grey80');text(.08,q,paste0(q*100,'%'),cex=.65)};segments(0,0,cos(a),sin(a),col='grey80');text(1.22*cos(a),1.22*sin(a),colnames(r),cex=.85);for(i in which)polygon(r[i,]/100*cos(a),r[i,]/100*sin(a),col=adjustcolor(c(blue,orange)[i],.15),border=c(blue,orange)[i],lwd=2)}
for(k in 1:2){start('radar',k);par(mar=c(2,1,3,1));if(k==1){radar(1:2);legend('bottom',rownames(r),col=c(blue,orange),lty=1,bty='n',horiz=TRUE)}else{par(mfrow=c(1,2));for(i in 1:2){radar(i);title(rownames(r)[i])}};dev.off()}
# Distribution families reuse included cell and cytokine data.
f<-read.csv('data/gallery-fluorescence.csv')$fluorescence
cy<-read.csv('data/gallery-dose.csv');gl<-unique(cy$condition)
for(k in 1:2){start('ecdf',k);if(k==1)plot(ecdf(f),verticals=TRUE,do.points=FALSE,main='',xlab='Protein fluorescence (a.u.)',ylab='Fraction of cells at or below x',col=blue,lwd=2) else {plot(NA,xlim=c(0,45),ylim=c(0,1),xlab='Cytokine concentration (ng/mL)',ylab='Fraction of samples at or below x');for(i in 1:3)lines(ecdf(cy$concentration[cy$condition==gl[i]]),col=c(blue,orange,'#555555')[i],lwd=2);legend('bottomright',gl,col=c(blue,orange,'#555555'),lty=1,bty='n')};dev.off()}
for(k in 1:2){start('ridgeline',k);par(mar=c(5,7,3,2));plot(NA,xlim=c(0,45),ylim=c(.8,4.5),yaxt='n',xlab='Cytokine concentration (ng/mL)',ylab='');axis(2,1:3,gl,tick=FALSE);for(i in 3:1){d<-density(cy$concentration[cy$condition==gl[i]],bw=if(k==1)1 else 2,from=0,to=45);polygon(c(d$x,rev(d$x)),c(i+d$y*5,rep(i,length(d$x))),col=adjustcolor(c(blue,orange,'#999999')[i],.6),border='grey40')};dev.off()}
# Ranking: identical values, dot versus lollipop.
rank<-data.frame(pathway=c('Stress','Transport','Metabolism','Signalling','Repair'),genes=c(12,19,35,27,16));write.csv(rank,'data/gallery-ranking.csv',row.names=FALSE)
for(k in 1:2){start('dot',k);par(mar=c(5,8,3,2));o<-order(rank$genes);plot(rank$genes[o],1:5,xlim=c(0,40),ylim=c(.5,5.5),yaxt='n',xlab='Number of annotated genes',ylab='',pch=19,col=blue,cex=1.4);axis(2,1:5,rank$pathway[o],tick=FALSE);if(k==2){segments(0,1:5,rank$genes[o],1:5,col=blue);points(rank$genes[o],1:5,pch=19,col=blue,cex=1.4)};dev.off()}
# Mean and 95% t confidence interval, same observations, two orientations.
mn<-sapply(gl,function(g)mean(cy$concentration[cy$condition==g]));err<-sapply(gl,function(g){z<-cy$concentration[cy$condition==g];qt(.975,length(z)-1)*sd(z)/sqrt(length(z))})
for(k in 1:2){start('interval',k);if(k==1){par(mar=c(5,8,3,2));plot(mn,1:3,xlim=c(0,18),ylim=c(.5,3.5),yaxt='n',xlab='Mean cytokine concentration (ng/mL)',ylab='',pch=19,col=blue);segments(mn-err,1:3,mn+err,1:3,lwd=2,col=blue);axis(2,1:3,gl,tick=FALSE)}else{plot(1:3,mn,xlim=c(.5,3.5),ylim=c(0,18),xaxt='n',xlab='Condition',ylab='Mean cytokine concentration (ng/mL)',pch=19,col=blue);arrows(1:3,mn-err,1:3,mn+err,angle=90,code=3,length=.08,col=blue);axis(1,1:3,gl)};mtext('Points: means; intervals: 95% t confidence intervals',side=3,line=.5,cex=.9);dev.off()}
# Areas: one total versus its components over the same time axis.
area<-data.frame(hour=0:5,A=c(5,8,14,22,30,35),B=c(3,4,8,15,20,24),C=c(2,3,5,8,12,16));write.csv(area,'data/gallery-area.csv',row.names=FALSE)
for(k in 1:2){start('area',k);plot(NA,xlim=c(0,5),ylim=c(0,80),xlab='Time (hours)',ylab='Biomass (mg/L)');if(k==1){polygon(c(area$hour,rev(area$hour)),c(rowSums(area[-1]),rep(0,6)),col=adjustcolor(blue,.6),border=blue)}else{lo<-rep(0,6);for(i in 1:3){hi<-lo+area[[i+1]];polygon(c(area$hour,rev(area$hour)),c(hi,rev(lo)),col=c(blue,orange,gray)[i],border='white');lo<-hi};legend('topleft',c('Taxon A','Taxon B','Taxon C'),fill=c(blue,orange,gray),bty='n')};dev.off()}
# Bubble areas encode prevalence, not radii.
bub<-data.frame(taxon=LETTERS[1:5],abundance=c(3,7,12,20,35),prevalence=c(10,25,40,70,95));write.csv(bub,'data/gallery-bubble.csv',row.names=FALSE)
for(k in 1:2){start('bubble',k);plot(NA,xlim=c(0,60),ylim=c(0,6),yaxt='n',xlab='Mean relative read abundance (%)',ylab='');axis(2,1:5,paste('Taxon',bub$taxon),tick=FALSE);points(bub$abundance,1:5,pch=21,bg=adjustcolor(blue,.5),col=blue,cex=sqrt(bub$prevalence)/2);if(k==2)text(bub$abundance+5,1:5,paste0(bub$prevalence,'%'),adj=0);legend('bottomright',y.intersp=2.5,legend=paste0(c(10,40,95),'% samples'),pch=21,pt.bg=adjustcolor(blue,.5),pt.cex=sqrt(c(10,40,95))/2,col=blue,bty='n',cex=.8);dev.off()}
# Simulated log2 expression; genuine t tests and BH adjustment.
base<-runif(120,4,12);effect<-c(rep(0,80),rep(-2,20),rep(2,20))
a<-matrix(rnorm(720,rep(base,6),.7),120,6);b<-matrix(rnorm(720,rep(base+effect,6),.7),120,6)
lfc<-rowMeans(b)-rowMeans(a);avg<-(rowMeans(a)+rowMeans(b))/2
padj<-p.adjust(sapply(1:120,function(i)t.test(a[i,],b[i,])$p.value),'BH');sig<-padj<.05 & abs(lfc)>=1
write.csv(data.frame(gene=paste0('G',1:120),mean_log2_expression=avg,log2_difference=lfc,padj=padj),'data/gallery-gene-results.csv',row.names=FALSE)
for(id in c('volcano','ma'))for(k in 1:2){start(id,k);xx<-if(id=='volcano')lfc else avg;yy<-if(id=='volcano')-log10(padj) else lfc;plot(xx,yy,pch=19,col=if(k==1)'grey60' else ifelse(sig,blue,'grey75'),xlab=if(id=='volcano')'Mean log2 expression difference (treatment − control)' else 'Mean log2 expression',ylab=if(id=='volcano')'−log10(BH-adjusted p-value)' else 'Mean log2 expression difference');if(id=='ma')abline(h=0,lty=2,col='grey50');if(k==2){if(id=='volcano'){abline(v=c(-1,1),h=-log10(.05),lty=2,col='grey60')};legend('top',inset=c(0,-.12),xpd=NA,horiz=TRUE,c('Adjusted p < 0.05 and |difference| ≥ 1','Other genes'),pch=19,col=c(blue,'grey75'),bty='n',cex=.7)};dev.off()}
# Correlation matrix, same assays in two orders.
mat<-cbind(a[1:4,1:6]);cm<-cor(t(mat));rownames(cm)<-colnames(cm)<-paste('Gene',LETTERS[1:4]);write.csv(cm,'data/gallery-correlation.csv')
for(k in 1:2){start('correlation',k);par(mar=c(5,6,3,7));o<-if(k==1)1:4 else hclust(as.dist(1-cm),method='average')$order;z<-cm[o,o];pal<-colorRampPalette(c('#2166ac','white','#b2182b'))(101);plot(NA,xlim=c(.5,4.5),ylim=c(.5,4.5),axes=FALSE,xlab='',ylab='',xaxs='i',yaxs='i');for(i in 1:4)for(j in 1:4){rect(j-.5,4-i+.5,j+.5,4-i+1.5,col=pal[round((z[i,j]+1)*50)+1],border='white');text(j,5-i,sprintf('%.2f',z[i,j]),col=if(abs(z[i,j])>.65)'white' else 'black')};axis(1,1:4,colnames(z),tick=FALSE);axis(2,4:1,rownames(z),tick=FALSE);par(xpd=NA);for(j in 1:101)rect(4.7,.5+(j-1)*4/101,4.9,.5+j*4/101,col=pal[j],border=NA);text(5.05,c(.5,2.5,4.5),c('-1','0','1'),adj=0);dev.off()}
# UpSet-style exclusive intersections for three sets.
member<-rbind(c(1,0,0),c(0,1,0),c(0,0,1),c(1,1,0),c(1,0,1),c(0,1,1),c(1,1,1));cnt<-c(24,18,12,15,8,6,5)
write.csv(data.frame(member,count=cnt),'data/gallery-intersections.csv',row.names=FALSE)
for(k in 1:2){start('upset',k);layout(matrix(1:2,2),heights=c(2,1));o<-if(k==1)1:7 else order(cnt,decreasing=TRUE);par(mar=c(0,5,2,2),xaxs='i');barplot(cnt[o],space=0,col=blue,border='white',xaxt='n',ylab='Genes in exact intersection',xlim=c(0,7),ylim=c(0,28));text((1:7)-.5,cnt[o]+1,cnt[o]);par(mar=c(3,5,1,2),xaxs='i');plot(NA,xlim=c(.5,7.5),ylim=c(.5,3.5),axes=FALSE,xlab='',ylab='');axis(2,1:3,c('List A','List B','List C'),las=1,tick=FALSE);for(j in 1:7){points(rep(j,3),1:3,pch=19,col='grey85');idx<-which(member[o[j],]==1);if(length(idx)>1)segments(j,min(idx),j,max(idx),lwd=2);points(rep(j,length(idx)),idx,pch=19)};dev.off()}
# Network layouts represent the same undirected associations.
edges<-rbind(c(1,2),c(1,3),c(2,3),c(3,4),c(4,5),c(4,6),c(5,6));write.csv(data.frame(from=LETTERS[edges[,1]],to=LETTERS[edges[,2]]),'data/gallery-network.csv',row.names=FALSE)
for(k in 1:2){start('network',k);par(mar=c(2,2,2,2));ang<-seq(0,2*pi,length.out=7)[1:6];xy<-if(k==1)cbind(cos(ang),sin(ang)) else rbind(c(-1,.5),c(-1,-.5),c(-.3,0),c(.3,0),c(1,.5),c(1,-.5));plot(xy,type='n',xlim=c(-1.4,1.4),ylim=c(-1.3,1.3),asp=1,axes=FALSE,xlab='',ylab='');segments(xy[edges[,1],1],xy[edges[,1],2],xy[edges[,2],1],xy[edges[,2],2],col='grey55',lwd=2);points(xy,pch=21,bg='white',col=blue,cex=4);text(xy,LETTERS[1:6]);dev.off()}
# PCA of the same simulated gene-expression samples.
fit<-prcomp(t(cbind(a,b)),center=TRUE,scale.=FALSE);pc<-fit$x[,1:2];var<-100*fit$sdev^2/sum(fit$sdev^2);write.csv(data.frame(sample=paste0(rep(c('C','T'),each=6),rep(1:6,2)),pc),'data/gallery-pca.csv',row.names=FALSE)
for(k in 1:2){start('pca',k);plot(pc,pch=rep(c(16,17),each=6),col=rep(c(blue,orange),each=6),xlab=sprintf('PC1 (%.1f%% variance)',var[1]),ylab=sprintf('PC2 (%.1f%% variance)',var[2]),cex=1.2);if(k==2)text(pc,labels=paste0(rep(c('C','T'),each=6),rep(1:6,2)),pos=3,cex=.75);legend('top',inset=c(0,-.12),xpd=NA,horiz=TRUE,c('Control','Treatment'),pch=c(16,17),col=c(blue,orange),bty='n');dev.off()}
